INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Erstellen des Pflichtenhefts nach DIN 69901-5 Teil der Planung?', 2, '[{"text": "Ja", "correct": true, "because": "Definiert Umsetzung früh"}, {"text": "Nein", "correct": false, "because": "Es gehört zur Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat das Pflichtenheft nach DIN 69901-5?', 3, '[{"text": "Umsetzungsvorschläge des Auftragnehmers festlegen", "correct": true, "because": "Antwort auf Lastenheft"}, {"text": "Kosten direkt reduzieren", "correct": false, "because": "Kein primäres Ziel"}, {"text": "Teamstruktur festlegen", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Pflichtenheft beschreibt die Lösung. b) Es wird erst nach Projektstart erstellt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Planung ist entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte gehören nach DIN 69901-5 ins Pflichtenheft?', 4, '[{"text": "Technische Lösungsvorschläge", "correct": true, "because": "Beschreiben Umsetzung"}, {"text": "Unklare Annahmen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Realisierungsdetails", "correct": true, "because": "Spezifizieren Vorgehen"}, {"text": "Abnahmebedingungen", "correct": true, "because": "Regeln Übergabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Pflichtenheft nach DIN 69901-5 geplant werden?', 2, '[{"text": "Nein", "correct": true, "because": "Umsetzung unklar"}, {"text": "Ja", "correct": false, "because": "Risiko von Missverständnissen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Pflichtenheft ist nach DIN 69901-5 schlecht formuliert?', 3, '[{"text": "Irgendwas wird geliefert", "correct": true, "because": "Zu vage"}, {"text": "App mit 3 Modulen bis Q3", "correct": false, "because": "Klar und spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Pflichtenheft nach DIN 69901-5 nur für IT-Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Projekte"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist nach DIN 69901-5 im Pflichtenheft zentral?', 3, '[{"text": "Konkrete Umsetzungsvorschläge", "correct": true, "because": "Antwort auf Anforderungen"}, {"text": "Teamzusammensetzung", "correct": false, "because": "Kein Fokus"}, {"text": "Kostenübersicht", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Pflichtenheft basiert auf dem Lastenheft. b) Es ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Pflichtenheft nach DIN 69901-5?', 3, '[{"text": "Umsetzung bleibt unklar", "correct": true, "because": "Fehlende Basis"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Missverständnisse möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Pflichtenheft nach DIN 69901-5 vage formuliert sein?', 2, '[{"text": "Nein", "correct": true, "because": "Klarheit erforderlich"}, {"text": "Ja", "correct": false, "because": "Widerspricht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein Pflichtenheft nach DIN 69901-5?', 3, '[{"text": "Backup mit SQL bis 15. Mai", "correct": true, "because": "Spezifisch und klar"}, {"text": "Irgendwas sichern", "correct": false, "because": "Zu ungenau"}, {"text": "Team soll etwas liefern", "correct": false, "because": "Nicht konkret"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Pflichtenheft nach DIN 69901-5 nur für den Auftragnehmer relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Auftraggeber braucht Klarheit"}, {"text": "Ja", "correct": false, "because": "Beide Seiten betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören nach DIN 69901-5 ins Pflichtenheft?', 4, '[{"text": "Technische Spezifikationen", "correct": true, "because": "Beschreiben Lösung"}, {"text": "Vage Wünsche", "correct": false, "because": "Fehlt Präzision"}, {"text": "Zeitliche Umsetzung", "correct": true, "because": "Planen Ablauf"}, {"text": "Abnahmekriterien", "correct": true, "because": "Regeln Fertigstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss das Pflichtenheft nach DIN 69901-5 dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit nötig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Pflichtenheft?', 3, '[{"text": "Vertragliche Grundlage schaffen", "correct": true, "because": "Bindet beide Seiten"}, {"text": "Kosten direkt festlegen", "correct": false, "because": "Späterer Schritt"}, {"text": "Team motivieren", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Pflichtenheft ohne Lastenheft erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Lastenheft ist Basis"}, {"text": "Ja", "correct": false, "because": "Fehlende Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert das Erstellen eines Pflichtenhefts?', 3, '[{"text": "Unklares Lastenheft", "correct": true, "because": "Fehlende Anforderungen"}, {"text": "Klares Team", "correct": false, "because": "Fördert Erstellung"}, {"text": "Gute Technik", "correct": false, "because": "Unterstützt Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Pflichtenheft spezifiziert die Umsetzung. b) Es ist nur für technische Details.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Pflichtenhefts?', 3, '[{"text": "Einheitliche Umsetzung sichern", "correct": true, "because": "Klarheit für alle"}, {"text": "Zeit verlängern", "correct": false, "because": "Kein Ziel"}, {"text": "Unklarheit schaffen", "correct": false, "because": "Gegenteil"}]');
